<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operación | Adbana</title><link rel="stylesheet" href="/css/panel.css"><script src="/js/panel.js"></script><script defer src="/js/alpine.min.js"></script></head>
<body><div x-data="panel" x-cloak>
<form class="login card" x-show="!user" @submit.prevent="login()">
<p class="brand">ADBANA</p><h1>Tu restaurante, en marcha</h1><p class="muted">Ingresa con tu cuenta de dueño o cajero.</p>
<label x-show="registro">Nombre del restaurante<input x-model="restauranteNombre" :required="registro" maxlength="120"></label><label x-show="registro">Tu nombre<input x-model="nombre" :required="registro" maxlength="120"></label><label>Correo<input type="email" x-model="email" required autocomplete="username"></label><label>Contraseña<input type="password" x-model="password" :minlength="registro ? 8 : 1" required autocomplete="current-password"></label>
<p class="alert" x-show="error" x-text="error" role="alert"></p><button class="primary wide" :disabled="busy" x-text="registro ? 'Crear restaurante' : 'Ingresar'">Ingresar</button><button type="button" class="wide" @click="registro=!registro;error=''" x-text="registro ? 'Ya tengo cuenta' : 'Crear mi restaurante'"></button>
</form>
<template x-if="user"><div>
<header class="top"><div><strong class="brand">ADBANA</strong><br><small x-text="user.restaurante?.nombre"></small></div><div><span x-text="user.name + ' · ' + user.rol"></span> <button @click="logout()" :disabled="busy">Salir</button></div></header>
<main class="shell"><nav class="nav" aria-label="Secciones">
<template x-for="item in [['venta','Punto de venta'],['pedidos','Pedidos'],['cocina','Cocina'],['mesas','Mesas'],['caja','Mi caja']].filter(i => i[0]==='cocina' ? user.permisos.cocina : i[0]==='caja' ? user.permisos.caja : user.permisos.pedidos)" :key="item[0]"><button :class="{active:tab===item[0]}" @click="tab=item[0]" x-text="item[1]"></button></template>
<template x-if="user.rol==='dueno'"><div class="actions"><button @click="tab='productos'">Productos y stock</button><button @click="tab='ventas';verReporte()">Ventas y gastos</button><button @click="tab='equipo';verUsuarios()">Equipo</button></div></template>
<button @click="accion(()=>actualizar())" :disabled="busy">Actualizar</button><a :href="'/c/'+user.restaurante?.slug" target="_blank" rel="noopener">Ver carta ↗</a></nav>
<p class="alert" role="alert" x-show="error" x-text="error"></p><p class="alert success" role="status" x-show="aviso" x-text="aviso"></p>

<section x-show="tab==='venta'" class="cols"><div class="card"><h1>Punto de venta</h1><form class="row" @submit.prevent="pagina=1;accion(()=>actualizar())"><input aria-label="Buscar productos" x-model="q" placeholder="Busca una bebida o un plato"><button>Buscar</button></form>
<div class="grid"><template x-for="p in productos" :key="p.id"><button class="product" :disabled="busy || !p.activo || p.stock<1" @click="agregar(p)"><strong x-text="p.nombre"></strong><span x-text="money(p.precio)"></span><small x-text="p.activo ? 'Stock: '+p.stock : 'Inactivo'"></small></button></template></div>
<div class="row"><button :disabled="pagina<=1 || busy" @click="pagina--;accion(()=>actualizar())">Anterior</button><small x-text="pagina+' / '+ultima"></small><button :disabled="pagina>=ultima || busy" @click="pagina++;accion(()=>actualizar())">Siguiente</button></div></div>
<div class="card"><h2>Pedido actual</h2><p x-show="!lineas.length" class="muted">Selecciona productos para comenzar.</p><template x-for="p in lineas" :key="p.id"><div class="row"><span x-text="p.nombre"></span><div class="actions"><button :disabled="busy" @click="quitar(p)" :aria-label="'Quitar '+p.nombre">−</button><span x-text="p.cantidad"></span><button :disabled="busy" @click="agregar(p)" :aria-label="'Agregar '+p.nombre">+</button></div><strong x-text="money(p.precio*p.cantidad)"></strong></div></template>
<div class="sep"></div><div class="row"><strong>Total</strong><span class="tot" x-text="money(total)"></span></div>
<label>Cliente<input x-model="cliente" maxlength="120" :disabled="busy"></label><label>Atención<select x-model="tipo" :disabled="busy"><option value="recojo">Mostrador / para llevar</option><option value="mesa">En mesa</option><option value="delivery">Delivery</option></select></label>
<label x-show="tipo==='mesa'">Mesa<input x-model="mesa" maxlength="20" :disabled="busy"></label><label x-show="tipo==='delivery'">Dirección<input x-model="direccion" maxlength="255" :disabled="busy"></label><label x-show="tipo==='delivery'">Teléfono<input x-model="telefono" maxlength="30" :disabled="busy"></label><label>Notas<textarea x-model="notas" maxlength="500" :disabled="busy"></textarea></label>
<button x-show="user.permisos.caja" class="primary wide" :disabled="busy || !lineas.length || !caja" @click="guardarVenta(true)">Registrar y cobrar</button><button class="wide" :disabled="busy || !lineas.length" @click="guardarVenta(false)">Enviar pedido a cocina</button><p class="muted" x-show="user.permisos.caja && !caja">Abre tu turno en «Mi caja» para cobrar.</p></div></section>

<section x-show="['pedidos','cocina'].includes(tab)"><h1 x-text="tab==='cocina'?'Comandas de cocina':'Pedidos abiertos'"></h1><p class="muted">Se actualizan cada 15 segundos. El cobro finaliza y entrega el pedido.</p><p x-show="!pedidos.length">No hay pedidos pendientes.</p><div class="grid"><template x-for="p in pedidos" :key="p.id"><article class="card order"><div class="row"><h2 x-text="'#'+p.id"></h2><span class="pill" x-text="p.estado"></span></div><strong x-text="p.cliente_nombre"></strong><p x-text="p.tipo + (p.mesa?' · Mesa '+p.mesa:'')"></p><small x-text="new Date(p.created_at).toLocaleString()"></small><template x-for="d in p.detalles" :key="d.id"><p x-text="d.cantidad+' × '+d.nombre_producto"></p></template><p x-show="p.notas" x-text="p.notas"></p><p x-show="p.direccion" x-text="p.direccion"></p><strong x-show="user.permisos.caja" x-text="money(p.total)"></strong><button class="primary wide" x-show="siguiente(p)" :disabled="busy" @click="estado(p,siguiente(p))" x-text="'Pasar a '+siguiente(p)"></button><button class="wide" x-show="tab!=='cocina' && user.permisos.caja" :disabled="busy || !caja" @click="prepararCobro(p)">Cobrar y entregar</button><button class="wide" x-show="user.permisos.caja" :disabled="busy" @click="estado(p,'cancelado')">Cancelar pedido</button></article></template></div></section>

<section x-show="tab==='mesas'"><h1>Mesas con pedidos abiertos</h1><p class="muted">Las mesas se identifican al registrar el pedido. Esta vista reúne sus pedidos activos.</p><p x-show="!mesas.length">No hay mesas con pedidos abiertos.</p><div class="grid"><template x-for="m in mesas" :key="m.nombre"><article class="card"><h2 x-text="'Mesa '+m.nombre"></h2><strong x-text="'Total pendiente: '+money(m.pedidos.reduce((s,p)=>s+Number(p.total),0))"></strong><template x-for="p in m.pedidos" :key="p.id"><div><p x-text="'#'+p.id+' · '+p.estado+' · '+money(p.total)"></p><button :disabled="!caja || busy" @click="prepararCobro(p)">Cobrar pedido</button></div></template></article></template></div></section>

<section x-show="tab==='caja'" class="cols"><div class="card"><h1>Mi turno de caja</h1><p class="muted">Los cobros quedan a tu nombre. El efectivo permanece bajo tu responsabilidad hasta rendirlo; cerrar el turno no transfiere dinero a otro cajero.</p><form x-show="!caja" @submit.prevent="abrirCaja()"><label>Efectivo inicial (S/)<input type="number" min="0" step=".01" x-model="inicial" required></label><button class="primary" :disabled="busy">Abrir caja</button></form>
<template x-if="caja"><div><p x-text="'Turno #'+caja.id+' · abierto '+new Date(caja.created_at).toLocaleString()"></p><div class="row"><span>Fondo inicial</span><strong x-text="money(caja.saldo_inicial)"></strong></div><template x-for="(valor,medio) in resumen?.ventas_por_medio || {}" :key="medio"><div class="row"><span x-text="'Ventas '+medio"></span><strong x-text="money(valor)"></strong></div></template><div class="row"><span>Entradas</span><span x-text="money(resumen?.entradas)"></span></div><div class="row"><span>Salidas</span><span x-text="money(resumen?.salidas)"></span></div><div class="row"><strong>Efectivo esperado</strong><strong x-text="money(resumen?.efectivo_esperado)"></strong></div><form @submit.prevent="cerrarCaja()"><label>Efectivo contado (S/)<input type="number" min="0" step=".01" x-model="contado" required></label><button class="primary" :disabled="busy">Cerrar y registrar diferencia</button></form></div></template>
<template x-if="cierre"><div class="alert success"><h2>Turno cerrado</h2><p x-text="'Esperado: '+money(cierre.efectivo_esperado)"></p><p x-text="'Contado: '+money(cierre.efectivo_contado)"></p><strong x-text="'Diferencia: '+money(cierre.diferencia)"></strong></div></template></div>
<form class="card" x-show="caja" @submit.prevent="moverCaja()"><h2>Movimiento de efectivo</h2><label>Tipo<select x-model="movimiento.tipo"><option value="entrada">Entrada</option><option value="salida">Salida</option></select></label><label>Monto<input type="number" min=".01" step=".01" x-model="movimiento.monto" required></label><label>Motivo<input x-model="movimiento.motivo" maxlength="255" required></label><button class="primary" :disabled="busy">Registrar movimiento</button><p class="muted">Los movimientos de efectivo y los gastos contables se registran por separado.</p></form></section>

<template x-if="user.rol==='dueno'"><div>
<section x-show="tab==='productos'" class="cols"><div class="card"><h1>Productos</h1><form @submit.prevent="guardarProducto()"><label>Nombre<input x-model="producto.nombre" maxlength="150" required></label><div class="row"><label>Precio de venta<input type="number" min="0" step=".01" x-model="producto.precio" required></label><label>Costo<input type="number" min="0" step=".01" x-model="producto.costo" required></label></div><label>Categoría<select x-model="producto.categoria_id"><option value="">Sin categoría</option><template x-for="c in categorias" :key="c.id"><option :value="c.id" x-text="c.nombre"></option></template></select></label><p class="muted">Registra cada presentación como producto: por ejemplo, «Caja de cerveza», precio por caja y stock en cajas. No comparte stock con botellas individuales.</p><label x-show="!producto.id">Stock inicial<input type="number" min="0" step="1" x-model="producto.stock"></label><label>Stock mínimo<input type="number" min="0" step="1" x-model="producto.stock_minimo"></label><label><input type="checkbox" x-model="producto.activo" style="width:auto"> Disponible para venta</label><button class="primary" :disabled="busy">Guardar producto</button></form><div class="sep"></div><template x-for="p in productos" :key="p.id"><div class="row"><span x-text="p.nombre+' · '+money(p.precio)+' · stock '+p.stock"></span><button @click="editar(p)">Editar</button></div></template><div class="actions"><button :disabled="pagina<=1 || busy" @click="pagina--;accion(()=>actualizar())">Anterior</button><button :disabled="pagina>=ultima || busy" @click="pagina++;accion(()=>actualizar())">Siguiente</button></div></div>
<div class="list"><form class="card" @submit.prevent="guardarCategoria()"><h2>Nueva categoría</h2><label>Nombre<input x-model="categoriaNombre" required maxlength="100"></label><button :disabled="busy">Crear categoría</button></form><form class="card" @submit.prevent="moverStock()"><h2>Ajustar inventario</h2><label>Producto<select x-model="stockForm.producto_id" required><option value="">Selecciona</option><template x-for="p in productos" :key="p.id"><option :value="p.id" x-text="p.nombre"></option></template></select></label><label>Movimiento<select x-model="stockForm.tipo"><option value="entrada">Entrada de mercadería</option><option value="salida">Salida / merma</option><option value="ajuste">Conteo físico</option></select></label><label x-show="stockForm.tipo!=='ajuste'">Cantidad<input type="number" min="1" step="1" x-model="stockForm.cantidad"></label><label x-show="stockForm.tipo==='ajuste'">Stock contado<input type="number" min="0" step="1" x-model="stockForm.stock_real"></label><label>Motivo<input x-model="stockForm.motivo" required maxlength="255"></label><button class="primary" :disabled="busy">Registrar</button></form></div></section>
<section x-show="tab==='ventas'" class="cols"><div class="card"><h1>Ventas del día</h1><form class="row" @submit.prevent="verReporte()"><input type="date" aria-label="Fecha del reporte" x-model="fecha" required><button :disabled="busy">Consultar</button></form><template x-if="reporte"><div><template x-for="k in ['ventas','costo_vendido','ganancia_bruta','gastos','ganancia_neta']" :key="k"><div class="row"><span x-text="k.replaceAll('_',' ')"></span><strong x-text="money(reporte[k])"></strong></div></template><p x-text="reporte.pedidos_entregados+' pedidos entregados'"></p><h2>Más vendidos</h2><template x-for="(p,n) in reporte.top_productos" :key="n"><p x-text="p.producto+' · '+p.cantidad+' unidades'"></p></template></div></template></div><form class="card" @submit.prevent="guardarGasto()"><h2>Registrar gasto</h2><label>Descripción<input x-model="gasto.descripcion" required maxlength="255"></label><label>Monto<input type="number" min=".01" step=".01" x-model="gasto.monto" required></label><label>Categoría<input x-model="gasto.categoria" maxlength="50"></label><button class="primary" :disabled="busy">Guardar gasto</button></form></section>
<section x-show="tab==='equipo'" class="cols"><div class="card"><h1>Equipo</h1><template x-for="u in usuarios" :key="u.id"><div class="row"><span x-text="u.name+' · '+u.rol+' · '+(u.activo?'Activo':'Desactivado')"></span><button x-show="['cajero','mozo','mozo_cajero','cocina'].includes(u.rol)" :disabled="busy" @click="activarUsuario(u)" x-text="u.activo?'Desactivar':'Activar'"></button></div></template></div><form class="card" @submit.prevent="crearUsuario()"><h2>Nuevo integrante</h2><label>Rol<select x-model="nuevoUsuario.rol"><option value="cajero">Cajero</option><option value="mozo">Mozo sin cobro</option><option value="mozo_cajero">Mozo con cobro (turno propio)</option><option value="cocina">Cocina</option></select></label><label>Nombre<input x-model="nuevoUsuario.name" required maxlength="120"></label><label>Correo<input type="email" x-model="nuevoUsuario.email" required></label><label>Contraseña<input type="password" x-model="nuevoUsuario.password" minlength="8" required autocomplete="new-password"></label><button class="primary" :disabled="busy">Crear integrante</button></form></section>
</div></template>
</main></div></template>
<div class="modal" x-show="cobro" role="dialog" aria-modal="true" aria-label="Cobrar pedido"><form class="card dialog" @submit.prevent="pagar()"><h2 x-text="'Cobrar pedido #'+cobro?.id"></h2><p class="tot" x-text="money(cobro?.total)"></p><label>Medio de pago<select x-model="medio"><option value="efectivo">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="tarjeta">Tarjeta</option></select></label><label x-show="medio==='efectivo'">Efectivo recibido<input type="number" min="0" step=".01" x-model="recibido"></label><p x-show="medio==='efectivo'" x-text="'Vuelto: '+money(Math.max(0,vuelto))"></p><p class="alert" x-show="error" x-text="error"></p><p class="muted">Para pagos digitales, verifica la recepción en tu cuenta antes de confirmar.</p><button class="primary wide" :disabled="busy || !caja || (medio==='efectivo' && vuelto<0)">Confirmar cobro y entrega</button><button type="button" class="wide" :disabled="busy" @click="cobro=null">Volver</button></form></div>
<div class="modal" x-show="comprobante" role="dialog" aria-modal="true" aria-label="Constancia de venta"><div class="card dialog receipt"><h2 x-text="user?.restaurante?.nombre"></h2><p>Constancia interna de venta</p><p x-text="'Pedido #'+comprobante?.id"></p><p x-text="comprobante?.cliente_nombre"></p><template x-for="d in comprobante?.detalles || []" :key="d.id"><div class="row"><span x-text="d.cantidad+' × '+d.nombre_producto"></span><span x-text="money(d.subtotal)"></span></div></template><div class="sep"></div><p x-text="'Total: '+money(comprobante?.total)"></p><p x-text="'Pago: '+comprobante?.medio_pago"></p><p x-text="'Recibido: '+money(comprobante?.recibido)"></p><p x-text="'Vuelto: '+money(comprobante?.vuelto)"></p><small>No es comprobante de pago electrónico SUNAT.</small><button class="primary wide" @click="imprimir()">Imprimir</button><button class="wide" @click="comprobante=null">Cerrar</button></div></div>
</div></body></html>
